@Component("facility-handler")
@ProcessingGroup("facility-processing-group")
public class FacilityEventHandler {
	
	// core constructor
	FacilityEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateFacilityEvent
     */
    @EventHandler
    public void handle( CreateFacilityEvent event) {
        entityManager.persist(new Facility(event.getFacilityId(), event.getName(), event.getFacilityCode(), event.getAddress(), event.getHealthSystem(), event.getDepartments(), event.getCareTeams(), event.getLaboratories(), event.getImagingCenters(), event.getPharmacies(), event.getInventoryItems(), event.getFacilityType()));
    }

    /*
     * @param	event UpdateFacilityEvent
     */
    @EventHandler
    public Facility handle( UpdateFacilityEvent event) {
    	entityManager.merge(new Facility(event.getFacilityId(), event.getName(), event.getFacilityCode(), event.getAddress(), event.getHealthSystem(), event.getDepartments(), event.getCareTeams(), event.getLaboratories(), event.getImagingCenters(), event.getPharmacies(), event.getInventoryItems(), event.getFacilityType()));
    }
    
    /*
     * @param	event DeleteFacilityEvent
     */
    @EventHandler
    public void on( DeleteFacilityEvent event) {
    	Facility entity = new Facility();
   
    	// ------------------------------------------
    	// apply the FacilityId
    	// ------------------------------------------
    	entity.setFacilityId( event.getFacilityId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final FacilityRepository facilityEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(FacilityEventHandler.class.getName());

}
